import json, glob, os
base = '/root/autodl-tmp/distrib_canary_collapse/results'
METHODS = ['naive_xcorr', 'diff_xcorr', 'threshold_onset', 'perm_granger', 'ty_granger']
files = sorted(glob.glob(os.path.join(base, '**', '5method_leadlag.json'), recursive=True))
out = {}
for f in files:
    with open(f) as fh:
        d = json.load(fh)
    parts = f.replace(base + '/', '').split('/')
    exp_name = parts[1]
    alpha = d.get('alpha', d.get('meta', {}).get('alpha'))
    seed = d.get('seed', d.get('meta', {}).get('seed'))
    n_perm = d.get('config', {}).get('n_perm', d.get('meta', {}).get('n_perm'))
    pairs_data = d.get('pairs', [])
    exp_key = exp_name
    out[exp_key] = {'alpha': alpha, 'seed': seed, 'n_perm': n_perm, 'data': {}}
    for pair_data in pairs_data:
        if 'canary' in pair_data:
            canary = pair_data['canary']
            downstream = pair_data['downstream']
        else:
            fwd = pair_data.get('forward', {})
            canary = fwd.get('canary', '')
            downstream = fwd.get('downstream', '')
        pair_label = canary + '->' + downstream
        out[exp_key]['data'][pair_label] = {}
        for dk in ['forward', 'reverse']:
            dd = pair_data.get(dk, {})
            out[exp_key]['data'][pair_label][dk] = {}
            for mn in METHODS:
                m = dd.get(mn, {})
                if not m:
                    continue
                out[exp_key]['data'][pair_label][dk][mn] = {
                    'p': m.get('p_value'),
                    's': m.get('significant'),
                    'fp': m.get('fdr_p'),
                    'fs': m.get('significant_fdr')
                }
print(json.dumps(out))
"

